import{_ as a,o,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Contratos do Cloud, sincronização e revisão","description":"","frontmatter":{"title":"Contratos do Cloud, sincronização e revisão","docId":"developer.cloud","translationKey":"developer.cloud","locale":"pt","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"06ae46545d1366d4f456c78a0e6583ea0338afbd496467e4d25b3abe1a5430fb","translationRevision":"898da8f756958ffdd92bb80f4b2a5a9831c8453c5c6e746a964a5b5021435200","order":180},"headers":[],"relativePath":"pt/developer/cloud.md","filePath":"pt/developer/cloud.md","lastUpdated":1794611623000}'),r={name:"pt/developer/cloud.md"};function t(n,e,d,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="cloud-contracts-synchronization-and-review" tabindex="-1">Contratos do Cloud, sincronização e revisão <a class="header-anchor" href="#cloud-contracts-synchronization-and-review" aria-label="Permalink to &quot;Contratos do Cloud, sincronização e revisão {#cloud-contracts-synchronization-and-review}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Desenvolva recursos de configuração de conta e catálogo para a instância Cloud provisionada. A operação somente local continua válida. Para trabalho autenticado, use uma conta/backend dedicado de teste e o encaminhamento nativo da sessão; esta documentação não comprova aceitação de tokens de portador em produção nem entre dois dispositivos.</p><p>O responsável verificado pelo contrato é <a href="https://github.com/nglmercer/RemakeBackend" target="_blank" rel="noreferrer">nglmercer/RemakeBackend</a>, com <a href="https://github.com/nglmercer/RemakeBackend/blob/master/docs/CLOUD-API-V2.md" target="_blank" rel="noreferrer">contratos de configuração v2</a> e <a href="https://github.com/nglmercer/RemakeBackend/blob/master/docs/CLOUD-API-V3.md" target="_blank" rel="noreferrer">superfícies v3</a> adicionais. Tipos portáteis e transporte de cliente sob responsabilidade do backend são representados localmente em <code>crates/cloud-contracts</code> e <code>crates/cloud-client</code>. Durabilidade e autenticação no desktop continuam sendo responsabilidades do host.</p><h2 id="gate-and-stage-operations" tabindex="-1">Condicione e prepare operações <a class="header-anchor" href="#gate-and-stage-operations" aria-label="Permalink to &quot;Condicione e prepare operações {#gate-and-stage-operations}&quot;">​</a></h2><ol><li>Descubra métodos nativos com <code>rpc.discover</code>; um host mais antigo pode manter visualizações legadas.</li><li>Deixe o host verificar <code>/api/v2/capabilities</code> da instância antes de usar um endpoint condicionado a capacidades. Nunca fixe uma capacidade anunciada pelo servidor em uma flag apenas do navegador.</li><li>Use a origem provisionada pelo operador. Compilações de lançamento não aceitam substituições arbitrárias da origem em execução.</li><li>Visualize a migração e os conflitos, mantenha bases congeladas e gravações incertas e envie apenas a operação revisada.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync.v2.migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> globals.typed.replace</span></span></code></pre></div><p>Esses comandos inspecionam esquemas; não migram uma conta nem salvam valores de variáveis.</p><h2 id="current-implementation" tabindex="-1">Implementação atual <a class="header-anchor" href="#current-implementation" aria-label="Permalink to &quot;Implementação atual {#current-implementation}&quot;">​</a></h2><p>V2 tem estado/armazenamento/coordenador nativos, migração v1 protegida, revisão de conflitos, reconstrução e reconciliação de plugins instalados. A adoção é explícita e limitada à conta; instalações legadas sem marcação permanecem no caminho legado. A aceitação completa entre dois desktops e alguns adaptadores de produto continuam incompletos. A configuração de época de gravação para toda a conta tem consequências irreversíveis no servidor explicadas na revisão da migração.</p><p>V3 adiciona catálogo, equipes, integrações, recursos, overlays e pacotes por trás de capacidades. Metadados de catálogo não substituem a verificação de plugins assinados. A importação usa o diário do proprietário; confira enabled ao aplicar/importar perfil. A aplicação de pacotes registra etapas interrompidas em vez de reproduzi-las automaticamente. O acesso de leitura por relay do Cloud não deve ser confundido com autoridade de mutação da colaboração direta.</p><h2 id="expected-result-and-recovery" tabindex="-1">Resultado esperado e recuperação <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;Resultado esperado e recuperação {#expected-result-and-recovery}&quot;">​</a></h2><p>Alterações de configuração mantêm limites de identidade, revisão e análise. Changes de Automations é apenas local; Variables revisadas usam métodos nativos tipados reais e não sincronizam valores brutos. Changes de Overlays não está mesclado. Em um conflito, compare registros base/locais/novos do Cloud; em uma confirmação desconhecida, resolva a intenção mantida. Um erro HTTP que permite nova tentativa nunca autoriza repetir uma mutação. <a href="./collaboration.html">Colaboração</a> trata separadamente da autoridade sobre o host em execução.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p><code>TIKTOOLS_CLOUD_ORIGIN</code> usa runtime → valor compilado → padrão em debug, mas compilado → padrão em release, que ignora overrides runtime. Vazio, <code>off</code>, <code>none</code> desativam apenas na camada aplicável. Aceita origem HTTPS sem credenciais/caminho/query/fragmento; HTTP só loopback explícito. Debug isolado: <code>TIKTOOLS_CLOUD_ORIGIN=http://127.0.0.1:8787 bun run start</code>; release: <code>TIKTOOLS_CLOUD_ORIGIN=https://cloud.example bun scripts/task.ts rust build -p tiktools-desktop --release --locked</code>. Identidade de outra origem não restaura: confira origem/conta antes de autenticar. Padrão compilado não prova disponibilidade.</p><p>Siga <a href="./../user/cloud/changes.html#operational-details">migração e recuperação por modo</a>. Coordene dispositivos antes da política irreversível de época, preserve contagens/resultados e consulte estado após barreira ambígua, sem repeti-la para descobrir se ocorreu. A recuperação congela entradas e revisão aprovadas; revisão vencida precisa ser reconstruída antes de retomar, que não envia escrita Cloud.</p>`,16)])])}const h=a(r,[["render",t]]);export{m as __pageData,h as default};
